using System.Collections.Concurrent;
using AfriWallet.Merchants.PaymentDecision.Application.Abstractions;
using AfriWallet.Merchants.PaymentDecision.Domain.Decisions;
namespace AfriWallet.Merchants.PaymentDecision.Infrastructure;
public sealed class SandboxPaymentIntentDecisionReader:IPaymentIntentDecisionReader{private readonly Dictionary<Guid,PaymentIntentDecisionSnapshot> _items=new();public void Set(PaymentIntentDecisionSnapshot s)=>_items[s.PaymentIntentId]=s;public Task<PaymentIntentDecisionSnapshot?> GetAsync(Guid id,CancellationToken ct=default){ct.ThrowIfCancellationRequested();_items.TryGetValue(id,out var r);return Task.FromResult(r);}}
public sealed class InMemoryMerchantPaymentDecisionRepository:IMerchantPaymentDecisionRepository{private readonly ConcurrentDictionary<Guid,MerchantPaymentDecision> _items=new();public Task AddAsync(MerchantPaymentDecision d,CancellationToken ct=default){if(!_items.TryAdd(d.DecisionId,d))throw new InvalidOperationException("Payment decision already exists.");return Task.CompletedTask;}public Task SaveAsync(MerchantPaymentDecision d,CancellationToken ct=default){_items[d.DecisionId]=d;return Task.CompletedTask;}public Task<MerchantPaymentDecision?> GetAsync(Guid id,CancellationToken ct=default){_items.TryGetValue(id,out var r);return Task.FromResult(r);}public Task<MerchantPaymentDecision?> GetActiveByPaymentIntentAsync(Guid id,CancellationToken ct=default)=>Task.FromResult(_items.Values.Where(x=>x.PaymentIntentId==id&&x.Status!=PaymentAuthorizationDecisionStatus.Superseded).OrderByDescending(x=>x.CreatedAtUtc).FirstOrDefault());}
public sealed class InMemoryMerchantPaymentDecisionAuditStore:IMerchantPaymentDecisionAuditStore{private readonly ConcurrentQueue<MerchantPaymentDecisionAuditEvent> _events=new();public Task AppendAsync(MerchantPaymentDecisionAuditEvent e,CancellationToken ct=default){_events.Enqueue(e);return Task.CompletedTask;}public Task<IReadOnlyCollection<MerchantPaymentDecisionAuditEvent>> GetAsync(Guid id,CancellationToken ct=default){IReadOnlyCollection<MerchantPaymentDecisionAuditEvent> r=_events.Where(x=>x.DecisionId==id).ToArray();return Task.FromResult(r);}}
public sealed class SystemMerchantPaymentDecisionClock:IMerchantPaymentDecisionClock{public DateTimeOffset UtcNow=>DateTimeOffset.UtcNow;}
